def count_Substrings(s):
    count = 0
    prefix_sum = 0
    prefix_dict = {0: 1}

    for i, char in enumerate(s):
        digit = int(char)
        prefix_sum += digit

        if (prefix_sum - (i + 1)) in prefix_dict:
            count += prefix_dict[prefix_sum - (i + 1)]

        if prefix_sum - (i + 1) not in prefix_dict:
            prefix_dict[prefix_sum - (i + 1)] = 0
        prefix_dict[prefix_sum - (i + 1)] += 1

    return count
